// Uses one JSON payload generated by backend #79's canonical_identity and TestClient.
// Positive paths are test-only receipts, not production calibration or GPU evidence.
async (page, payload) => {
  if (!payload?.contract_only || !payload?.receipt_cases?.length || !payload?.canonical_cases?.length) {
    throw new Error("Generate backend parity inputs first; no demo data fallback is allowed");
  }
  const checks = [];
  const check = (value, label) => { if (!value) throw new Error(label); checks.push(label); };
  const errors = [];
  const onError = (error) => errors.push(error.message);
  page.on("pageerror", onError);
  await page.route("**/api/**", (route) => route.fulfill({contentType: "application/json", body: JSON.stringify(
    new URL(route.request().url()).pathname === "/api/health" ? {ok: true, capabilities: {source_optimization: true}}
      : {ok: true, settings: {ssh: {}, llm: {}}, tasks: []})}));
  await page.reload();
  await page.waitForFunction(() => state.apiHealthy);
  const base = payload.base_identity;
  const resultsFor = (record, planner) => ({
    evidence_summary: [record], diagnoses: [],
    source_optimization: {schema_version: "v2.source_optimization.v1", status: "completed", trials: []},
    optimization_rounds: [
      {schema_version: "v2.optimization_round.v1", round_index: 0, trial_id: base.source_trial_id,
        parent_source_sha256: base.source_sha256, evidence_ids: [], analysis: {}, plan: {}, validation: {}, acceptance: {}, artifacts: {}},
      {schema_version: "v2.optimization_round.v1", round_index: 1, trial_id: "CONTRACT_ONLY-analysis",
        parent_source_sha256: base.source_sha256, evidence_ids: [record.evidence_id],
        analysis: {basis: "eligible_metrics_and_source", confidence: "low"}, plan: {source: planner, decision: "stop"},
        validation: {}, acceptance: {decision: "stop"}, artifacts: {evidence_binding: {
          device_id: base.device_id, shape_id: base.shape_id, dtype: base.dtype, kernel_names: [base.kernel_name]}, excluded_evidence: []}},
    ],
  });
  async function render(record, planner) {
    return page.evaluate(({record, results}) => {
      stopTaskPolling(); state.task = {task_id: "CONTRACT_ONLY-identity", project_name: "契约检查，不是真机结果", status: "completed", execution_mode: "source_optimization"};
      state.taskResults = results; state.taskEvents = []; renderTaskDetail(); renderApiResults(); activateView("resultsView");
      const identity = evidenceCanonicalIdentity(record);
      return {values: identity.values, issues: identity.issues, planning: evidencePlanningStatus(record),
        reference: evidenceReferenceStatus(record, evidencePlanningEntry(results.optimization_rounds[1], results))};
    }, {record, results: resultsFor(record, planner)});
  }
  for (const item of payload.canonical_cases) {
    const actual = await page.evaluate((row) => {
      const identity = evidenceCanonicalIdentity(row);
      return {values: identity.values, issues: identity.issues};
    }, item.row);
    check(await page.evaluate(({actual, expected}) => sameEvidenceContext(actual, expected), {actual, expected: item.expected}), `${item.id}: exact Python canonical values/reasons, including null and invalid types`);
  }
  for (const item of payload.receipt_cases) {
    const qualified = item.api_planning_eligible;
    for (const kind of ["raw", "api"]) {
      for (const planner of ["llm", "rule_based"]) {
        const label = `${item.id}/${kind}/${planner}`;
        const actual = await render(item[kind], planner);
        check(await page.evaluate(({actual, expected}) => sameEvidenceContext({values: actual.values, issues: actual.issues}, expected),
          {actual, expected: item.identity}), `${label}: same JSON yields the backend's identity decision`);
        check((actual.planning === "eligible") === qualified && actual.reference.used === qualified, `${label}: eligibility/reference agrees with API recomputation and planner filtering`);
        const summary = await page.locator("#evidenceTrustSummary").innerText();
        check(summary.includes(`${qualified ? 1 : 0} 条可用于优化分析`) && (qualified || summary.includes("0 条归因已验证")), `${label}: summary never promotes rejected identity`);
        check(await page.locator('#apiResultsPanel [data-round-part="evidence"] .badge.best').count() === (qualified ? 1 : 0), `${label}: actual-use badge matches qualification for model/rule`);
        await page.locator("#apiResultsAdvanced").evaluate((el) => { el.open = true; });
        const cells = await page.locator("#evidenceTrustTable tbody tr td").allInnerTexts();
        const hint = item.identity.issues.some((reason) => reason.endsWith("_identity_conflict")) ? "身份字段冲突，引用待核验" : "身份字段无效，引用待核验";
        check(qualified ? cells[4] === "可用于优化分析" : item.identity.issues.length
          ? cells[4] === hint && cells[5].startsWith(hint) && cells[6].includes(hint)
          : cells[4] !== "可用于优化分析" && !cells[5].includes("实际引用的决策依据"), `${label}: qualification, usage and calibration details share one interpretation`);
      }
    }
  }
  const blocked = payload.receipt_cases.find((item) => item.id === "source_hash_null");
  for (const [name, width, height] of [["desktop", 1440, 1000], ["mobile", 390, 844]]) {
    await render(blocked.raw, "llm"); await page.setViewportSize({width, height});
    for (const [view, panel] of [["taskView", "#taskDetailPanel"], ["resultsView", "#apiResultsPanel"]]) {
      await page.locator(`.tab-button[data-view-target="${view}"]`).click();
      await page.locator(`${panel} .optimization-round`).evaluateAll((rows) => rows.forEach((row) => { row.open = true; }));
      check(await page.evaluate(() => document.documentElement.scrollWidth <= innerWidth + 1), `${name}/${view}: null-conflict labels fit`);
      check(await page.locator(`${panel} [data-round-part="evidence"] .badge.best`).count() === 0, `${name}/${view}: replay cannot show actual use for null conflict`);
    }
  }
  check(errors.length === 0, `No browser JS errors: ${errors.join("; ")}`);
  page.off("pageerror", onError);
  return {passed: checks.length, checks, backend_revision: payload.backend_revision,
    canonical_cases: payload.canonical_cases.length, receipt_cases: payload.receipt_cases.length,
    contractOnly: true, liveApiValidation: false, realGpuValidation: false};
}
